package com.bookstore.service; import com.bookstore.entity.Order; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service public class MailNotificationService { private final JavaMailSender sender; @Value("${app.mail.enabled:false}") private boolean enabled; public MailNotificationService(JavaMailSender s){sender=s;} public void orderPlaced(Order o){if(!enabled){System.out.println("[EMAIL DEMO] Order #"+o.getId()+" placed for "+o.getUser().getEmail());return;} SimpleMailMessage m=new SimpleMailMessage();m.setTo(o.getUser().getEmail());m.setSubject("BookStore Order #"+o.getId());m.setText("Your order has been placed. Total: "+o.getTotal());sender.send(m);} }
